import React, { useEffect, useState } from 'react';
import SearchBarUnified from './components/SearchBarUnified';
import ProductSlider from './components/ProductSlider';
import CategorySlider from './components/CategorySlider';
import { getCategories, getSectionGroups } from './services/api';
import './styles.css';

const ORDER = ['Gastronomía','Indumentaria','Hogar','Tecnología','Deportes','Belleza'];


export default function App(){
  const [categorias, setCategorias] = useState([]);
  const [groupsSemana, setGroupsSemana] = useState([]);
  const [groupsDestacados, setGroupsDestacados] = useState([]);

  useEffect(() => {
    (async () => {
      // Categorías
      const catsRaw = await getCategories();
      const catsOrdered = [...catsRaw].sort((a,b)=>{
        const ai = ORDER.indexOf(a.name), bi = ORDER.indexOf(b.name);
        return (ai===-1?999:ai) - (bi===-1?999:bi);
      });
     setCategorias(catsOrdered); // ya vienen con imageUrl desde la BD

      // Grupos por sección (slugs definidos en backend)
      const [gs, gd] = await Promise.all([
        getSectionGroups('solo-semana'),
        getSectionGroups('destacados')
      ]);
      setGroupsSemana(gs || []);
      setGroupsDestacados(gd || []);
    })().catch(e => console.error(e));
  }, []);

  return (
    <div className="page">
      <header className="header">
        <div className="logo">
          <a href="/"><img src="/logo.png" alt="Conecta Pinamar" /></a>
        </div>
        <SearchBarUnified />
      </header>

      <section>
        <h2 className="title">SOLO POR ESTA SEMANA</h2>
        <ProductSlider id="semana" groups={groupsSemana} />
      </section>

      <section>
        <h2 className="title">CATEGORÍAS</h2>
        <CategorySlider categories={categorias} />
      </section>

      <section>
        <h2 className="title">DESTACADOS</h2>
        <ProductSlider id="destacados" groups={groupsDestacados} />
      </section>
    </div>
  );
}
